string Check(string name) {
  var s = Shader.Find(name);
  if (s == null) return name + ": NOT FOUND\n";
  var msgs = UnityEditor.ShaderUtil.GetShaderMessages(s);
  int errs = 0;
  var sb = new System.Text.StringBuilder();
  sb.Append(name).Append(" supported=").Append(s.isSupported).Append(" msgs=").Append(msgs.Length).Append('\n');
  foreach (var m in msgs) {
    if ((int)m.severity == 0) { // Error typically 0
      errs++;
      sb.Append(" E: ").Append(m.message).Append('\n');
    }
  }
  // Also dump severity names for first few
  int shown = 0;
  foreach (var m in msgs) {
    if (shown >= 8) break;
    sb.Append("  [").Append(m.severity).Append("] ").Append(m.message).Append('\n');
    shown++;
  }
  sb.Append(" errorCountApprox=").Append(errs).Append('\n');
  return sb.ToString();
}
