var sb = new System.Text.StringBuilder();
int missing = 0;
var all = AssetDatabase.GetAllAssetPaths();
foreach (var path in all) {
  if (!path.StartsWith("Assets/")) continue;
  // Only Resources-included assets matter for the build failure we saw
  if (path.IndexOf("/Resources/", System.StringComparison.OrdinalIgnoreCase) < 0) continue;
  if (!path.EndsWith(".asset") && !path.EndsWith(".prefab") && !path.EndsWith(".unity")) continue;
  var objs = AssetDatabase.LoadAllAssetsAtPath(path);
  foreach (var o in objs) {
    if (o == null) { missing++; sb.AppendLine("NULL obj in " + path); continue; }
    if (o is MonoBehaviour mb) {
      if (MonoScript.FromMonoBehaviour(mb) == null) { missing++; sb.AppendLine("Missing MB script: " + path + " / " + o.name); }
    } else if (o is ScriptableObject so) {
      var ms = MonoScript.FromScriptableObject(so);
      if (ms == null) { missing++; sb.AppendLine("Missing SO script: " + path + " / " + o.name); }
    }
  }
}
sb.Insert(0, "Resources missing-script count: " + missing + "\n");
// Also specifically check moved ASE assets are NOT under Resources and still exist
sb.AppendLine("ASE Do Shiny path: " + AssetDatabase.GUIDToAssetPath(AssetDatabase.FindAssets("QFX Do Shiny")[0]));
return sb.ToString();

